{
  "decision-match-unlabeled-copy-removals": "WITH ranked AS (SELECT line_no, depot_code, edition_code, ROW_NUMBER() OVER (PARTITION BY depot_code, edition_code ORDER BY line_no) AS copy_no FROM copy_requests), completed AS (SELECT depot_code, edition_code, SUM(copy_qty) AS copies FROM removal_tally GROUP BY depot_code, edition_code) SELECT r.line_no, r.depot_code, r.edition_code FROM ranked AS r LEFT JOIN completed AS c ON c.depot_code = r.depot_code AND c.edition_code IS r.edition_code WHERE r.copy_no > COALESCE(c.copies, 0) ORDER BY r.line_no",
  "decision-matched-store-lift-with-balanced-pairs": "WITH changes AS (SELECT pair_code, arm_code, 1.0 * (post_units - pre_units) / weeks_n AS weekly_change FROM store_period WHERE pre_units IS NOT NULL AND post_units IS NOT NULL) SELECT COUNT(*) AS complete_pairs, CAST(ROUND(100.0 * AVG(t.weekly_change - c.weekly_change)) AS INTEGER) AS mean_lift_hundredths FROM changes AS t JOIN changes AS c ON c.pair_code = t.pair_code WHERE t.arm_code = 'trial' AND c.arm_code = 'control'",
  "decision-maximize-packed-production-mix": "WITH quantities(n) AS (VALUES (0), (1), (2), (3), (4)), mixes AS (SELECT a.n AS a_units, b.n AS b_units, a.n + b.n AS total_units, a.n * pa.slots_per_unit + b.n * pb.slots_per_unit AS slots_used, a.n * pa.staff_minutes_per_unit + b.n * pb.staff_minutes_per_unit AS staff_minutes_used FROM quantities AS a CROSS JOIN quantities AS b CROSS JOIN product AS pa CROSS JOIN product AS pb WHERE pa.product_code = 'A' AND pb.product_code = 'B') SELECT a_units, b_units, total_units, slots_used, staff_minutes_used FROM mixes CROSS JOIN shift WHERE slots_used <= packing_slots AND staff_minutes_used <= staff_minutes ORDER BY total_units DESC, a_units DESC LIMIT 1",
  "decision-measure-margin-after-graded-returns": "WITH returns_by_lot AS (SELECT lot_code, SUM(refund_units) AS refunded, SUM(shelf_units) AS recovered FROM return_check GROUP BY lot_code), totals AS (SELECT s.sku_code, SUM((s.sold_units - COALESCE(r.refunded, 0)) * s.unit_price) AS net_sales_cents, SUM((s.sold_units - COALESCE(r.recovered, 0)) * s.unit_cost) AS net_cost_cents FROM sale_lot AS s LEFT JOIN returns_by_lot AS r ON r.lot_code = s.lot_code GROUP BY s.sku_code) SELECT sku_code, net_sales_cents, net_cost_cents, net_sales_cents - net_cost_cents AS gross_margin_cents FROM totals ORDER BY sku_code COLLATE BINARY ASC"
}
